<script setup lang="ts">
import { reactive, ref } from 'vue'
import { onLoad } from '@dcloudio/uni-app'
import AppPage from '../../components/AppPage.vue'
import Icon from '../../components/Icon.vue'
import { useHealthStore } from '../../stores/health'
import { back, home, numeric, toast } from '../../utils/ui'
const store=useHealthStore(),first=ref(false),error=ref('')
const form=reactive({name:'',goal:'减脂保肌',height:'',targetWeight:'',kcal:'',protein:'',carbs:'',fat:''})
const nutritionFields=[{key:'kcal' as const,label:'每日热量',unit:'kcal',placeholder:'例如 2100'},{key:'protein' as const,label:'蛋白质',unit:'g',placeholder:'例如 140'},{key:'carbs' as const,label:'碳水化合物',unit:'g',placeholder:'例如 240'},{key:'fat' as const,label:'脂肪',unit:'g',placeholder:'例如 65'}]
onLoad(q=>{store.hydrate();first.value=q?.first==='1';const p=store.data.profile;Object.assign(form,{name:p.name,goal:p.goal,height:p.height?.toString()||'',targetWeight:p.targetWeight?.toString()||''});for(const f of nutritionFields)form[f.key]=p.targets[f.key]?.toString()||''})
function save(){error.value='';try{const profile={name:form.name.trim(),goal:form.goal,height:numeric(form.height,'身高',50,250),targetWeight:numeric(form.targetWeight,'目标体重',20,350),targets:{kcal:numeric(form.kcal,'每日热量',1,10000),protein:numeric(form.protein,'蛋白质目标',1,1000),carbs:numeric(form.carbs,'碳水目标',1,1000),fat:numeric(form.fat,'脂肪目标',1,1000)}};if(store.saveProfile(profile)){first.value?home():back();toast('目标已保存')}}catch(e){error.value=(e as Error).message}}
</script>
<template><AppPage title="个人与目标"><text class="eyebrow">YOUR OWN PACE</text><text class="page-title">找到适合自己的节奏</text><text class="page-description">目标是方向，可以随着你的身体和生活调整。</text><view class="form-card"><view class="field"><text class="field-label">怎么称呼你<text class="field-note">选填</text></text><view class="input-wrap"><input aria-label="昵称" v-model="form.name" placeholder="你的昵称" maxlength="16" /></view></view><view class="field"><text class="field-label">当前目标</text><view class="choice-group"><button role="button" v-for="goal in ['减脂保肌','增肌塑形','维持健康']" :key="goal" class="choice" :class="{active:form.goal===goal}" @click="form.goal=goal">{{ goal }}</button></view></view><view class="form-grid"><view class="field"><text class="field-label">身高<text class="field-note">选填</text></text><view class="input-wrap"><input aria-label="身高" v-model="form.height" type="digit" placeholder="例如 175"/><text class="input-unit">cm</text></view></view><view class="field"><text class="field-label">目标体重<text class="field-note">选填</text></text><view class="input-wrap"><input aria-label="目标体重" v-model="form.targetWeight" type="digit" placeholder="例如 68"/><text class="input-unit">kg</text></view></view></view></view><view class="section-heading mt-16"><text class="section-title">每日营养目标</text><text class="pill">手动设置</text></view><text class="helper mb-16">填写你已确定的目标，也可以留空，稍后补充。这里不会自动生成减脂或训练处方。</text><view class="form-grid"><view v-for="f in nutritionFields" :key="f.key" class="field"><text class="field-label">{{ f.label }}</text><view class="input-wrap"><input :aria-label="f.label" v-model="form[f.key]" type="digit" :placeholder="f.placeholder"/><text class="input-unit">{{ f.unit }}</text></view></view></view><view class="notice"><Icon name="info" :size="18"/><text>热量和营养素目标分别填写。身体趋势比单日数字更有参考价值；BMI 仅作为辅助信息。</text></view><text v-if="error" class="error-message">{{ error }}</text><view class="save-bar"><button role="button" class="btn-primary" @click="save"><Icon name="check" tone="white" :size="18"/>{{ first?'保存，开启我的轻衡':'保存目标' }}</button><text class="helper">仅保存在当前设备，无需登录</text></view></AppPage></template>
